shader_type canvas_item;

uniform float glow : hint_range(0.0, 1.0) = 0.0;
uniform vec4 glow_color : source_color = vec4(0.6, 0.85, 1.0, 1.0);

void fragment() {
      COLOR.rgb = mix(COLOR.rgb, glow_color.rgb, glow);
}

uniform sampler2D albedo_tex : source_color, filter_linear_mipmap;
uniform sampler2D rough_tex : hint_default_white, filter_linear_mipmap;
uniform sampler2D normal_tex : hint_normal, filter_linear_mipmap;

group_uniforms paint;
uniform vec4 paint_tint : source_color = vec4(0.75, 0.22, 0.17, 1.0);
uniform float rust_amount : hint_range(0.0, 1.0) = 0.3;
group_uniforms;

group_uniforms surface;
uniform float roughness_scale : hint_range(0.0, 2.0) = 1.0;
uniform float normal_strength : hint_range(0.0, 2.0) = 1.0;
uniform float uv_scale : hint_range(0.25, 8.0) = 2.0;
group_uniforms;

uniform sampler2D as_color : source_color, filter_nearest;
uniform sampler2D as_data : filter_nearest;
uniform bool use_color = false;

void fragment() {
      if (use_color) {
              ALBEDO = texture(as_color, UV).rgb;
      } else {
              ALBEDO = texture(as_data, UV).rgb;
      }
